import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Claim } from '../claims/api';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade a person was given, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

/** `grade` is the one in force on the sheet's today, of their `grades` by from-date (none first).
 *  `version` is raised by every saved edit; an edit sends the version its form loaded. Their
 *  statements: how many were taken, and the last one's due-total and date (null until the first).
 *  `retiredFrom` is the date they are retired from (null: not retired); with it set at all they
 *  are `retired`, whatever the date. While `held`, their OPEN claims count in no live total. `patronIds` are the people they name
 *  as patrons, in the order named. */
export type Person = {
  id: number; sheetId: string; name: string; grade: Grade; grades: GradeFrom[]; version: number;
  statementCount: number; statedTotal: string | null; statementDate: string | null;
  retired: boolean; retiredFrom: string | null; held: boolean; patronIds: number[];
};
/** `gradeFrom` is the date an edit's grade applies from (blank: the sheet's today). */
export type PersonInput = { name: string; grade: string; gradeFrom: string };

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(p: Person, date: string): string {
  let found: GradeFrom | undefined;
  for (const g of p.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade ?? '';
}

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function listPeople(sheetId: string): Promise<Person[]> {
  return getJson<Person[]>(base(sheetId));
}

/** Add a person; refused (rejects) when the name is empty or already in use on the sheet. */
export function addPerson(sheetId: string, by: string, input: PersonInput): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** Edit a person loaded at `version`; refused (rejects) like an add, and with a 409 when someone
 *  else has saved the person since. */
export function updatePerson(sheetId: string, by: string, id: number, version: number, input: PersonInput): Promise<Person> {
  return putJson<Person>(`${base(sheetId)}/${id}?by=${encodeURIComponent(by)}`, { ...input, version });
}

/** Take a statement of the person: records their due-total now and binds each of their counting
 *  claims to the figure it shows now (unbinding the others). */
export function takeStatement(sheetId: string, by: string, id: number): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/statement?by=${encodeURIComponent(by)}`, {});
}

/** Retire the person from `from` (blank: the sheet's today); refused (rejects) when it is not a date. */
export function retirePerson(sheetId: string, by: string, id: number, from: string): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/retire?by=${encodeURIComponent(by)}`, { from });
}

/** Put the person on hold, or take them off it when they are held. */
export function holdPerson(sheetId: string, by: string, id: number): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/hold?by=${encodeURIComponent(by)}`, {});
}

/** Name another person on the sheet as one of the person's patrons; refused (rejects) for the
 *  person themselves or a patron already named. */
export function addPatron(sheetId: string, by: string, id: number, patronId: number): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/patrons?by=${encodeURIComponent(by)}`, { patronId });
}

export type QuickAddInput = { name: string; amount: string };

/** Add a DRAFT claim of `amount` (the sheet's today, empty note) to the named person, adding them
 *  first with grade A when the name is not on the sheet; refused (rejects), adding no one, when the
 *  name is empty or the claim would be refused. */
export function quickAdd(sheetId: string, by: string, input: QuickAddInput): Promise<Claim> {
  return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add?by=${encodeURIComponent(by)}`, input);
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED; a DRAFT or OPEN claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';
/** A change of a claim's status. */
export type ClaimAction = 'open' | 'settle' | 'void';

/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
 *  number on the sheet (given when opened; null while a draft or once voided), and its settled due
 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise). */
export type Claim = {
  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: number | null; settledDue: string | null; openedBy: string | null;
  stated: boolean; statedDue: string | null; corrects: number | null;
};
/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** Whether a claim is a correction: its amount is negative. */
export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
 *  SETTLED claim of the person. A blank date takes the sheet's today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

/** Change a claim's status; refused (rejects) when its status does not allow the change, or when the
 *  user settling it is the one who opened it. */
export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}`, {});
}

/** Whether a claim counts toward claimed, due-total and every total: only OPEN and SETTLED do. */
export const counts = (c: Claim) => c.status === 'OPEN' || c.status === 'SETTLED';

/** The claims that count in live totals: all but the OPEN claims of people on hold (their SETTLED
 *  claims still count). */
export function liveClaims(claims: Claim[], people: Array<{ id: number; held: boolean }> | undefined): Claim[] {
  const held = new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => !(c.status === 'OPEN' && held.has(c.personId)));
}

/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A claim's due-by (yyyy-MM-dd): its date plus the sheet's terms in days. */
export function dueBy(c: Claim, terms: number): string {
  const d = new Date(`${c.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's `today`. */
export const isOverdue = (c: Claim, terms: number, today: string) =>
  c.status === 'OPEN' && today !== '' && dueBy(c, terms) < today;
import { getJson, postJson } from '../../api/http';
import { counts, dueBy, isCorrection, isOverdue, type Claim } from '../claims/api';
import { sheetKey } from '../sheet/api';

/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
 *  (yyyy-MM-dd; null applies from the beginning of time). A grade with no rate is not listed. */
export type Rate = { sheetId: string; grade: string; pct: string; from: string | null };
/** A blank `from` sets the rate that applies from the beginning of time. */
export type RateInput = { grade: string; pct: string; from: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

export const ratesKey = (sheetId: string) => [...sheetKey(sheetId), 'rates'] as const;

/** The sheet's rates, by grade, then by from-date (none first). */
export function listRates(sheetId: string): Promise<Rate[]> {
  return getJson<Rate[]>(base(sheetId));
}

/** Set a grade's rate from a from-date, replacing the one with the same grade and from-date;
 *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
 *  from-date is not a date. */
export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
 *  before it; undefined (n/a) when the date is before every rate the grade has, or it has none. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.pct;
}

/** The rate in force on a date for each grade that has one then. */
export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
  const byGrade = new Map<string, string>();
  for (const r of rates ?? []) {
    const pct = rateOn(rates, r.grade, date);
    if (pct !== undefined) byGrade.set(r.grade, pct);
  }
  return byGrade;
}

/** Two-decimal text (may be negative) as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const t = text.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const value = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -value : value;
}

/** An amount times a percent, divided by 100, rounded half to even to two decimals, and at least
 *  the sheet's `floor` (a correction, a negative amount, has no floor); null (n/a) when there is no
 *  rate. Exact: worked in whole hundredths. */
export function dueOf(amount: string, pct: string | undefined, floor: string): string | null {
  if (pct === undefined) return null;
  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000, half to even.
  const cents = roundPct(hundredths(amount) * hundredths(pct));
  const least = hundredths(floor);
  return formatCents(cents < least && hundredths(amount) >= 0n ? least : cents);
}

/** What a claim's late charge goes by: the sheet's late percent, its terms (days) and its today. */
export type Late = { pct: string; terms: number; today: string };

/** The late charge on an OPEN claim's `figure`: the late percent of it for every full 30 days it is
 *  past its due-by on the sheet's today, rounded half to even to two decimals (0 when not overdue, and
 *  on a correction). */
export function lateCharge(c: Claim, figure: string, late: Late): bigint {
  if (isCorrection(c) || !isOverdue(c, late.terms, late.today)) return 0n;
  const days = (Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(c, late.terms)}T00:00:00Z`)) / 86_400_000;
  return roundPct(hundredths(figure) * hundredths(late.pct) * BigInt(Math.floor(days / 30)));
}

/** A person's grade in force on a date (yyyy-MM-dd). */
export type GradeOn = (date: string) => string;

/** A claim's due: the one fixed when it was settled (its late charge then frozen in), else its
 *  figure — the one bound by its person's last statement, else live at the rate in force on the
 *  claim's date of the grade in force then (`gradeOn`), at least the `floor` — with its late charge
 *  on the sheet's today on top. */
export function claimDue(c: Claim, rates: Rate[] | undefined, gradeOn: GradeOn, floor: string, late: Late): string | null {
  if (c.settledDue !== null) return c.settledDue;
  const figure = c.stated ? c.statedDue : dueOf(c.amount, rateOn(rates, gradeOn(c.date), c.date), floor);
  return figure === null ? null : formatCents(hundredths(figure) + lateCharge(c, figure, late));
}

/** A product of hundredths and a percent's hundredths (in 1/1_000_000) to cents, half to even
 *  (symmetric about zero). */
function roundPct(product: bigint): bigint {
  if (product < 0n) return -roundPct(-product);
  const whole = product / 10_000n;
  const rest = product % 10_000n;
  return rest > 5_000n || (rest === 5_000n && whole % 2n === 1n) ? whole + 1n : whole;
}

/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped); n/a
 *  when their grade today has no rate today (`pct`) and none of those claims keeps a settled or bound
 *  figure, or a live one at a grade no longer in force on the sheet's today. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
  floor: string, late: Late) {
  const own = claims.filter(counts);
  const now = gradeOn(late.today);
  const kept = (c: Claim) => c.settledDue !== null || (c.stated && c.statedDue !== null)
    || (gradeOn(c.date) !== now && rateOn(rates, gradeOn(c.date), c.date) !== undefined);
  if (pct === undefined && !own.some(kept)) return null;
  return sumDues(own.map((c) => claimDue(c, rates, gradeOn, floor, late)));
}

/** The overdue claims among those that count (`claims`, the live ones): their count and the sum
 *  of their due figures (n/a ones skipped). */
export function overdue(claims: Claim[], terms: number, today: string, dueOfClaim: (c: Claim) => string | null) {
  const late = claims.filter((c) => isOverdue(c, terms, today));
  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
}

/** Add up two-decimal dues, skipping n/a. */
export function sumDues(dues: Array<string | null>): string {
  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
}

function formatCents(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
}

/** A due as shown: n/a when there is none. */
export const showDue = (due: string | null) => due ?? 'n/a';
import { SheetBody } from '../../slots/defs/sheetBody';
import { DueTotal } from './DueTotal';
import { Overdue } from './Overdue';
import { Rates } from './Rates';

export const contributions = [
  SheetBody.fill({ order: 5, Component: Rates }),
  SheetBody.fill({ order: 25, Component: DueTotal }),
  SheetBody.fill({ order: 26, Component: Overdue }),
];
import { asFlag, useSearchParam } from '../../url/useSearchParam';

/** Whether retired people are listed. It lives in the URL (`retired`): off when the screen is first
 *  opened, and left as it is by loading a sheet. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** The "show retired" toggle. */
export function ShowRetired() {
  const [on, setOn] = useShowRetired();
  return (
    <label>
      <input type="checkbox" data-testid="show-retired" checked={on} onChange={(e) => setOn(e.target.checked || undefined)} />{' '}
      Show retired
    </label>
  );
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey, type Person } from '../people/api';
import { useFloor, useLate, useTerms } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimDue, listRates, overdue, ratesKey } from './api';

/** The sheet's overdue claims: how many of the claims that count are OPEN past their due-by, and
 *  their due (with its late charge) added up. */
export function Overdue({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const terms = useTerms(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byId = new Map<number, Person>((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => byId.has(c.personId));
  const late = overdue(live, terms, today, (c) => claimDue(c, rates.data, (d) => gradeOn(byId.get(c.personId)!, d), floor, charges));
  return (
    <p>
      Overdue <span data-testid="rollup-overdue-count">{late.count}</span>{' '}
      totalling <span data-testid="rollup-overdue-total">{late.total}</span>
    </p>
  );
}

